from abc import abstractmethod, ABCMeta
from prettytable import PrettyTable
import six


@six.add_metaclass(ABCMeta)
class RadioBase(object):
    def __init__(self, radio_ip, sm_ip, msm_ip):
        """
        Base class for different type of Radio modules. All inheriting class should
        define assign to self.radio_connection one of interface module from radio connection

        :param radio_ip: Radio ip
        :param sm_ip: system module ip connected with radio
        :param msm_ip: master system module ip
        """
        super(RadioBase, self).__init__()
        self._radio_ip = radio_ip
        self._sm_ip = sm_ip
        self._msm_ip = msm_ip
        self._raw_tx_power = None
        self._raw_tx_stat = None
        self._raw_front_end_gain_data = None
        self.release = None
        self.radio_connection = None

    @abstractmethod
    def all_tx_power(self):
        """
        Return all tx power in format {tx: power}.

        :return: tx power
        :rtype: dict
        """
    @abstractmethod
    def all_rx_power(self):
        """
        Return all rx power in format {rx: power}.

        :return: rx power
        :rtype: dict
        """

    @abstractmethod
    def lte_tx_power(self):
        """
        Return tx power for LTE technology.

        :return: tx power
        :rtype: dict
        """

    @abstractmethod
    def gsm_tx_power(self):
        """
        Return tx power for GSM technology.

        :return: tx power
        :rtype: dict
        """

    @abstractmethod
    def wcdma_tx_power(self):
        """
        Return tx power for WDMA technology.

        :return: tx power
        :rtype: dict
        """

    @abstractmethod
    def front_end_gain(self, antenna_number):
        """
        Return front end gain for rx.

        :return: front end gain
        :rtype: float
        """

    @abstractmethod
    def tx_carrier_data(self):
        """
        Return tx carrier data.

        :return: tx carrier data
        :rtype: dict
        """

    @abstractmethod
    def rx_carrier_data(self):
        """
        Return rx carrier data.

        :return: rx carrier data
        :rtype: dict
        """

    def run_radio_command(self, command):
        """
        Send command to radio module and run it

        :param command: rmod command
        :return: raw radio output
        :rtype: str
        """
        return self.radio_connection.execute_commands(command, self.release)

    def tx_power_table(self, tx_power_dict, technology=None):
        table = [[key, value] for key, value in tx_power_dict.items() if value != "OFF"]
        ptable = PrettyTable()
        ptable.field_names = ["TX", "Power"]
        if table:
            for values in table:
                ptable.add_row(values)
            return ptable
        elif technology and not tx_power_dict:
            return "Radio with ip: {} doesn't have {}".format(
                self._radio_ip, technology
            )
        elif technology and tx_power_dict:
            return "No tx power for {} on radio: {}".format(technology, self._radio_ip)
        return "No power on tx, radio ip: {}".format(self._radio_ip)

    def rx_power_table(self, rx_power_dict):
        table = [[key, value] for key, value in rx_power_dict.items() if value != "OFF"]
        ptable = PrettyTable()
        ptable.field_names = ["RX", "Power"]
        if table:
            for values in table:
                ptable.add_row(values)
            return ptable
        return "No power on rx, radio ip: {}".format(self._radio_ip)
